package org.slavicmyths.verify;
import java.util.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.core.component.DataComponents;import net.minecraft.world.item.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;
import static org.slavicmyths.verify.Stabilization269.*;
/** Runtime registry facts and source-audit inputs; no entity is spawned, no behavior approval. */
final class Census269 {
 static void run(){current="native_registry_census";var items=new ArrayList<Map<String,Object>>();for(var item:BuiltInRegistries.ITEM){var id=BuiltInRegistries.ITEM.getKey(item);if(!id.getNamespace().equals("slavicmyths"))continue;var stack=new ItemStack(item);var row=new LinkedHashMap<String,Object>();row.put("id",id.toString());row.put("java_class",item.getClass().getName());row.put("max_stack",stack.getMaxStackSize());row.put("durability",stack.getMaxDamage());row.put("food_component",stack.has(DataComponents.FOOD));row.put("tags",item.builtInRegistryHolder().tags().map(t->t.location().toString()).sorted().toList());if(item instanceof BlockItem b)row.put("block_class",b.getBlock().getClass().getName());items.add(row);}out.put("item_census",items);
 var entities=new ArrayList<Map<String,Object>>();for(var type:BuiltInRegistries.ENTITY_TYPE){var id=BuiltInRegistries.ENTITY_TYPE.getKey(type);if(!id.getNamespace().equals("slavicmyths"))continue;var row=new LinkedHashMap<String,Object>();row.put("id",id.toString());row.put("category",type.getCategory().getName());try{var entity=type.create(w);row.put("java_class",entity.getClass().getName());row.put("width",entity.getBbWidth());row.put("height",entity.getBbHeight());if(entity instanceof LivingEntity living){row.put("default_max_health",living.getMaxHealth());if(living.getAttribute(Attributes.ATTACK_DAMAGE)!=null)row.put("default_attack_damage",living.getAttributeValue(Attributes.ATTACK_DAMAGE));if(living.getAttribute(Attributes.MOVEMENT_SPEED)!=null)row.put("default_movement_speed",living.getAttributeValue(Attributes.MOVEMENT_SPEED));}check(true,"common server entity factory initializes "+id);}catch(Throwable error){row.put("factory_error",error.toString());check(false,"common server entity factory initializes "+id);}entities.add(row);}out.put("entity_census",entities);check(items.size()==923&&entities.size()==124,"actual current registry census923items124entities");out.put("census_scope","native registered classes/default attributes/tags only; no natural spawn, AI/combat, equipped effect or usefulness assertion");}
}
